insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_presentation','presentation','noun','a talk in which someone explains a subject to an audience, often using slides or pictures','[{"senseId":"presentation_1","meaning":"a talk in which someone explains a subject to an audience, often using slides or pictures","acceptedParaphrases":["talk","formal talk to an audience"],"masteryContexts":[{"contextId":"u10_31_presentation_meaning","text":"Her presentation on recycling included clear slides and a short video.","meaning":"a talk to an audience with information","wrongMeanings":["a written report handed in privately","a conversation between two friends","a test with no speaking"]},{"contextId":"u10_31_presentation_paraphrase","text":"The prize-giving ceremony ended with the presentation of the awards.","meaning":"the act of formally giving something to someone","wrongMeanings":["the selling of the awards","the design of the awards","the return of the awards"]}],"situationDistractors":["Two friends whispered to each other at the back of the bus.","Students wrote answers to a reading test in silence.","A teacher wrote the homework on the board.","A girl texted a friend.","A boy read silently on the bus.","A student did a written exercise alone."],"gapDistractors":[{"contextId":"u10_31_presentation_gap_1","answer":"presentation","wrong":["loneliness","literacy","recreation"]},{"contextId":"u10_31_presentation_gap_2","answer":"presentation","wrong":["loneliness","literacy","recreation"]},{"contextId":"u10_31_presentation_gap_3","answer":"presentation","wrong":["loneliness","literacy","recreation"]}],"spellingErrors":["presentasion","presantation","presentaton","presentashion","pressentation","presentaiton"],"wordFamilyForms":[{"form":"presentation","partOfSpeech":"noun","example":"Her presentation on recycling was excellent.","pedagogicallyUseful":true},{"form":"present","partOfSpeech":"verb","example":"Each group will present its findings to the class.","pedagogicallyUseful":true,"altExample":"Our group will present its project on Monday."},{"form":"presenter","partOfSpeech":"noun","example":"The television presenter introduced the next guest.","pedagogicallyUseful":true,"altExample":"The presenter of the podcast interviews a scientist every week."}],"masteryPassages":[{"passageId":"u10_31_presentation_passage_1","contextId":"u10_31_presentation_gap_1","text":"Each student must speak to the class for five minutes about a hobby. You can use slides to support your ____.","answer":"presentation"},{"passageId":"u10_31_presentation_passage_2","contextId":"u10_31_presentation_gap_2","text":"Dina stood at the front with her slides ready. She took a deep breath and began her ____ on renewable energy.","answer":"presentation"}],"contextDependentParaphrases":[],"wrongParaphrases":["private chat","written test","homework list"],"misleadingDistractors":["a private conversation between two friends","a written test with no speaking","a list of homework tasks"],"teacherNote":"Noun: a talk explaining a subject to an audience (give / make / do a presentation, a presentation on / about). Countable. A key speaking skill in this unit, linked with pronunciation and intonation. The verb present and the noun presenter are taught in the Word Family pathway."}]'::jsonb,'["present","presenter"]'::jsonb,'["give a presentation","a presentation on","a short presentation"]'::jsonb,'live'),
('vocab_pronunciation','pronunciation','noun','the way in which a word or language is spoken','[{"senseId":"pronunciation_1","meaning":"the way in which a word or language is spoken","acceptedParaphrases":["way of saying words","how words are spoken"],"masteryContexts":[{"contextId":"u10_32_pronunciation_meaning","text":"Listening to podcasts helped Carlos improve his English pronunciation.","meaning":"the way someone speaks a language","wrongMeanings":["the way someone spells words","the number of words someone knows","the speed someone writes"]},{"contextId":"u10_32_pronunciation_paraphrase","text":"The dictionary shows the pronunciation of each word using special symbols.","meaning":"how a particular word is said","wrongMeanings":["how a word is spelled","what a word means","where a word comes from"]}],"situationDistractors":["A student checked how many letters were in a long word.","A boy looked up what a new word meant in the dictionary.","A girl timed how fast she could read a page.","A student counted the pages in a book.","A boy copied a sentence neatly.","A girl underlined the title of her essay."],"gapDistractors":[{"contextId":"u10_32_pronunciation_gap_1","answer":"pronunciation","wrong":["loneliness","industry","literacy"]},{"contextId":"u10_32_pronunciation_gap_2","answer":"pronunciation","wrong":["loneliness","industry","literacy"]},{"contextId":"u10_32_pronunciation_gap_3","answer":"pronunciation","wrong":["loneliness","industry","employment"]}],"spellingErrors":["pronounciation","pronunsiation","pronunciasion","prononciation","pronuncation","pronunciaton"],"wordFamilyForms":[{"form":"pronunciation","partOfSpeech":"noun","example":"Her pronunciation has improved a lot.","pedagogicallyUseful":true},{"form":"pronounce","partOfSpeech":"verb","example":"How do you pronounce this word?","pedagogicallyUseful":true,"altExample":"Many learners find it hard to pronounce the sound “th”."},{"form":"mispronounce","partOfSpeech":"verb","example":"Visitors often mispronounce the name of our town.","pedagogicallyUseful":true,"altExample":"It is easy to mispronounce long scientific words."}],"masteryPassages":[{"passageId":"u10_32_pronunciation_passage_1","contextId":"u10_32_pronunciation_gap_1","text":"Paulo’s written English is excellent. However, people sometimes misunderstand him because his ____ is unclear.","answer":"pronunciation"},{"passageId":"u10_32_pronunciation_passage_2","contextId":"u10_32_pronunciation_gap_2","text":"The online dictionary has a small speaker symbol next to each word. If you click it, you can hear the correct ____.","answer":"pronunciation"}],"contextDependentParaphrases":[],"wrongParaphrases":["way of spelling words","meaning of words","speed of reading"],"misleadingDistractors":["the way words are spelled","the meaning of a word","the speed at which someone reads"],"teacherNote":"Noun: the way words or a language are spoken (good / clear pronunciation, the pronunciation of a word). Uncountable. Common spelling error: *pronounciation (the verb is pronounce, but the noun drops the o). The verb pronounce is taught in the Word Family pathway."}]'::jsonb,'["pronounce","mispronounce"]'::jsonb,'["clear pronunciation","the pronunciation of","practise pronunciation"]'::jsonb,'live'),
('vocab_intonation','intonation','noun','the rise and fall of the voice when speaking, which can change the meaning or show feelings','[{"senseId":"intonation_1","meaning":"the rise and fall of the voice when speaking, which can change the meaning or show feelings","acceptedParaphrases":["rise and fall of the voice","tone of voice"],"masteryContexts":[{"contextId":"u10_33_intonation_meaning","text":"A flat intonation can make a speaker sound bored or unfriendly.","meaning":"the way the voice goes up and down","wrongMeanings":["the speed at which someone speaks","the accent of a particular region","the number of words used"]},{"contextId":"u10_33_intonation_paraphrase","text":"In English, falling intonation usually shows that a statement is finished.","meaning":"the pattern of the voice at the end of a sentence","wrongMeanings":["the order of words in a sentence","the length of a sentence","the punctuation at the end of a sentence"]}],"situationDistractors":["A student counted the words in her essay.","A teacher changed the order of words on a slide.","A boy turned down the music in the next room.","A student checked her spelling.","A boy chose a font for his poster.","A girl measured the length of a table."],"gapDistractors":[{"contextId":"u10_33_intonation_gap_1","answer":"intonation","wrong":["employment","industry","literacy"]},{"contextId":"u10_33_intonation_gap_2","answer":"intonation","wrong":["employment","industry","literacy"]},{"contextId":"u10_33_intonation_gap_3","answer":"intonation","wrong":["employment","industry","loneliness"]}],"spellingErrors":["intonasion","intenation","intonaton","inttonation","intoneation","intonatoin"],"masteryPassages":[{"passageId":"u10_33_intonation_passage_1","contextId":"u10_33_intonation_gap_1","text":"You can often tell how someone feels from the way their voice rises and falls. Her ____ showed that she was not really happy.","answer":"intonation"},{"passageId":"u10_33_intonation_passage_2","contextId":"u10_33_intonation_gap_2","text":"In English, our voice usually goes up at the end of a yes/no question. This rising ____ shows the listener that we expect an answer.","answer":"intonation"}],"contextDependentParaphrases":[],"wrongParaphrases":["number of words","order of words","volume of noise"],"misleadingDistractors":["the number of words in a sentence","the order of words in a sentence","the loudness of background noise"],"teacherNote":"Noun: the rise and fall of the voice in speech (rising / falling intonation). Uncountable. Intonation shows questions, surprise, politeness or boredom. Boundary: pronunciation is how individual sounds and words are said; intonation is the pattern of the voice across a whole phrase."}]'::jsonb,'[]'::jsonb,'["rising intonation","falling intonation","flat intonation"]'::jsonb,'live'),
('vocab_vocabulary','vocabulary','noun','all the words that a person knows or uses, or all the words in a language','[{"senseId":"vocabulary_1","meaning":"all the words that a person knows or uses, or all the words in a language","acceptedParaphrases":["range of words","words a person knows"],"masteryContexts":[{"contextId":"u10_34_vocabulary_meaning","text":"Using a wide vocabulary in your essay will earn you higher marks.","meaning":"the range of words someone uses","wrongMeanings":["the grammar someone uses","the handwriting someone uses","the paragraphs someone uses"]},{"contextId":"u10_34_vocabulary_paraphrase","text":"Every science subject has its own special vocabulary that students must learn.","meaning":"the words used in a particular subject","wrongMeanings":["the equipment used in a laboratory","the books used in a subject","the rules used in experiments"]}],"situationDistractors":["A student checked that the verbs in her sentences were in the right order.","A boy practised saying difficult sounds in front of a mirror.","A teacher counted the spelling mistakes in an essay.","A student checked that his sentence had a full stop.","A girl practised the sound “th” in front of a mirror.","A boy timed how long his speech took."],"gapDistractors":[{"contextId":"u10_34_vocabulary_gap_1","answer":"vocabulary","wrong":["loneliness","recreation","employment"]},{"contextId":"u10_34_vocabulary_gap_2","answer":"vocabulary","wrong":["loneliness","recreation","employment"]},{"contextId":"u10_34_vocabulary_gap_3","answer":"vocabulary","wrong":["loneliness","recreation","employment"]}],"spellingErrors":["vocabulery","vocabularly","vocabluary","vocabularry","vocabularey","vocubulary"],"masteryPassages":[{"passageId":"u10_34_vocabulary_passage_1","contextId":"u10_34_vocabulary_gap_1","text":"Every week, Mei writes ten new words in a notebook and tests herself. As a result, her ____ has grown enormously.","answer":"vocabulary"},{"passageId":"u10_34_vocabulary_passage_2","contextId":"u10_34_vocabulary_gap_2","text":"Medicine has many difficult words. Medical students must learn a large amount of specialist ____.","answer":"vocabulary"}],"contextDependentParaphrases":[],"wrongParaphrases":["set of grammar rules","way of speaking","number of mistakes"],"misleadingDistractors":["the rules for putting words in order","the way words sound when spoken","the number of mistakes in a text"],"teacherNote":"Noun: the words a person knows or uses, or the words of a language or subject (a wide / limited vocabulary, increase your vocabulary, technical vocabulary). Usually uncountable in learning contexts. Boundary: vocabulary is words; grammar is how words are combined. Plural vocabularies is rare."}]'::jsonb,'[]'::jsonb,'["a wide vocabulary","increase your vocabulary","technical vocabulary"]'::jsonb,'live'),
('vocab_accurately','accurately','adverb','in a way that is correct and exact, without mistakes','[{"senseId":"accurately_1","meaning":"in a way that is correct and exact, without mistakes","acceptedParaphrases":["correctly","without mistakes"],"masteryContexts":[{"contextId":"u10_35_accurately_meaning","text":"The scientists measured the temperature accurately every hour.","meaning":"exactly, with no mistakes","wrongMeanings":["quickly and without care","loudly and clearly","occasionally and at random"]},{"contextId":"u10_35_accurately_paraphrase","text":"A good summary reports the writer’s ideas accurately and briefly.","meaning":"in a way that is true to the facts","wrongMeanings":["in a way that changes the meaning","at great length","in a way that copies every word"]}],"situationDistractors":["A boy rushed his homework and made lots of careless mistakes.","A girl shouted her answer before the teacher finished the question.","A student wrote such messy notes that nobody could read them.","A boy guessed the measurements without a ruler.","A girl wrote the wrong date on her work.","A student copied the numbers in the wrong order."],"gapDistractors":[{"contextId":"u10_35_accurately_gap_1","answer":"accurately","wrong":["reluctantly","lonely","overseas"]},{"contextId":"u10_35_accurately_gap_2","answer":"accurately","wrong":["reluctantly","lonely","nervously"]},{"contextId":"u10_35_accurately_gap_3","answer":"accurately","wrong":["reluctantly","lonely","rarely"]}],"spellingErrors":["accuratly","acurately","accuratelly","accuretely","accuratley","acuratly"],"wordFamilyForms":[{"form":"accurately","partOfSpeech":"adverb","example":"Measure each line accurately with a ruler.","pedagogicallyUseful":true},{"form":"accurate","partOfSpeech":"adjective","example":"The report gives an accurate picture of school life.","pedagogicallyUseful":true,"altExample":"Make sure your notes are accurate before the test."},{"form":"accuracy","partOfSpeech":"noun","example":"Examiners reward accuracy as well as range.","pedagogicallyUseful":true,"altExample":"The machine checks the accuracy of every measurement."}],"masteryPassages":[{"passageId":"u10_35_accurately_passage_1","contextId":"u10_35_accurately_gap_1","text":"In the science experiment, small mistakes can ruin the results. You must measure each liquid ____.","answer":"accurately"},{"passageId":"u10_35_accurately_passage_2","contextId":"u10_35_accurately_gap_2","text":"A good summary does not change the writer’s ideas. It reports them ____ and in fewer words.","answer":"accurately"}],"contextDependentParaphrases":[],"wrongParaphrases":["carelessly","loudly","unclearly"],"misleadingDistractors":["very quickly but carelessly","in a loud and confident way","in a way that is hard to understand"],"teacherNote":"Adverb: correctly and exactly (measure / describe / spell accurately). Linked to accurate (adjective) and accuracy (noun). Marking schemes reward using language accurately as well as widely. The adjective accurate and the noun accuracy are taught in the Word Family pathway."}]'::jsonb,'["accurate","accuracy"]'::jsonb,'["measure accurately","describe accurately","spell accurately"]'::jsonb,'live'),
('vocab_effectively','effectively','adverb','in a way that works well and produces the result that you want','[{"senseId":"effectively_1","meaning":"in a way that works well and produces the result that you want","acceptedParaphrases":["successfully","in a way that works well"],"masteryContexts":[{"contextId":"u10_36_effectively_meaning","text":"To communicate effectively, you need to listen as well as speak.","meaning":"in a way that achieves the aim","wrongMeanings":["in a way that wastes time","in a quiet and polite way","in a slow and careful way"]},{"contextId":"u10_36_effectively_paraphrase","text":"The poster campaign effectively reduced the amount of litter in the playground.","meaning":"with a successful result","wrongMeanings":["without any effect at all","by accident","for a short time only"]}],"situationDistractors":["A boy spent three hours on homework but did the wrong exercise.","A shop paid for a huge advert that nobody saw.","A girl explained her idea so badly that nobody understood.","A boy studied for hours but used the wrong notes.","A girl’s poster was so confusing that nobody understood it.","A plan to save money ended up costing more."],"gapDistractors":[{"contextId":"u10_36_effectively_gap_1","answer":"effectively","wrong":["reluctantly","lonely","overseas"]},{"contextId":"u10_36_effectively_gap_2","answer":"effectively","wrong":["reluctantly","lonely","overseas"]},{"contextId":"u10_36_effectively_gap_3","answer":"effectively","wrong":["lonely","overseas","academic"]}],"spellingErrors":["effectivly","efectively","effectivelly","effectivley","efectivly","effecktively"],"wordFamilyForms":[{"form":"effectively","partOfSpeech":"adverb","example":"She uses examples effectively in her essays.","pedagogicallyUseful":true},{"form":"effective","partOfSpeech":"adjective","example":"Mind maps are an effective way to revise.","pedagogicallyUseful":true,"altExample":"Regular practice is the most effective way to learn vocabulary."},{"form":"effectiveness","partOfSpeech":"noun","example":"The school measured the effectiveness of the new timetable.","pedagogicallyUseful":true,"altExample":"Teachers discussed the effectiveness of online lessons."}],"masteryPassages":[{"passageId":"u10_36_effectively_passage_1","contextId":"u10_36_effectively_gap_1","text":"Some students revise for hours without remembering much. Others use short, focused sessions and learn far more ____.","answer":"effectively"},{"passageId":"u10_36_effectively_passage_2","contextId":"u10_36_effectively_gap_2","text":"A good leader listens to the team and explains plans clearly. This helps everyone work together ____.","answer":"effectively"}],"contextDependentParaphrases":[],"wrongParaphrases":["slowly","expensively","secretly"],"misleadingDistractors":["in a slow and careful way","in an expensive way","in a way that nobody notices"],"teacherNote":"Adverb: in a way that produces the result wanted (communicate / work / use something effectively). Linked to effective (adjective) and effectiveness (noun). Boundary: effectively is about results; efficiently is about not wasting time or energy."}]'::jsonb,'["effective","effectiveness"]'::jsonb,'["communicate effectively","work effectively","use time effectively"]'::jsonb,'live'),
('vocab_develop','develop','verb','to grow or change into something bigger, stronger or more advanced, or to make something do this','[{"senseId":"develop_1","meaning":"to grow or change into something bigger, stronger or more advanced, or to make something do this","acceptedParaphrases":["build up","improve over time"],"masteryContexts":[{"contextId":"u10_37_develop_meaning","text":"Team sports help children develop confidence and social skills.","meaning":"to make a skill grow stronger","wrongMeanings":["to make a skill weaker","to hide a skill from others","to test a skill once"]},{"contextId":"u10_37_develop_paraphrase","text":"The company plans to develop an app that helps students learn new words.","meaning":"to create something new over time","wrongMeanings":["to sell something old","to repair something broken","to ban something completely"]}],"situationDistractors":["A boy stopped practising the guitar and forgot how to play.","A town closed its library and shrank to half its size.","A girl kept writing her essays in exactly the same way for years.","A boy stopped going to piano lessons and forgot how to play.","A girl’s handwriting stayed exactly the same for years.","A shop got smaller and smaller until it closed."],"gapDistractors":[{"contextId":"u10_37_develop_gap_1","answer":"develop","wrong":["succeed","reflect","contribute"]},{"contextId":"u10_37_develop_gap_2","answer":"develop","wrong":["succeed","reflect","contribute"]},{"contextId":"u10_37_develop_gap_3","answer":"develop","wrong":["succeed","encourage","reflect"]}],"spellingErrors":["develope","devellop","devlop","developp","divelop","develup"],"wordFamilyForms":[{"form":"develop","partOfSpeech":"verb","example":"The course helps students develop their writing.","pedagogicallyUseful":true},{"form":"development","partOfSpeech":"noun","example":"The early years are important for a child’s development.","pedagogicallyUseful":true,"altExample":"Reading helps the development of a child’s imagination."},{"form":"developed","partOfSpeech":"adjective","example":"Children in developed countries usually stay at school until eighteen.","pedagogicallyUseful":true,"altExample":"Her writing style is now more developed and mature."}],"masteryPassages":[{"passageId":"u10_37_develop_passage_1","contextId":"u10_37_develop_gap_1","text":"Joining the debate club helped Raj in many ways. He began to ____ his speaking skills and his confidence.","answer":"develop"},{"passageId":"u10_37_develop_passage_2","contextId":"u10_37_develop_gap_2","text":"The company spent three years on a new learning app. Engineers worked hard to ____ it before it was launched.","answer":"develop"}],"contextDependentParaphrases":[],"wrongParaphrases":["shrink","stay the same","lose"],"misleadingDistractors":["to make something smaller and weaker","to stop something from changing","to lose a skill through not using it"],"teacherNote":"Verb: to grow or improve, or to make something grow or improve (develop a skill, develop into, develop an idea); also to create something new (develop a product). Common spelling error: *developpe / *develope. The noun development and the adjective developed are taught in the Word Family pathway."}]'::jsonb,'["development","developed"]'::jsonb,'["develop a skill","develop an idea","develop into"]'::jsonb,'live'),
('vocab_opinion','opinion','noun','what a person thinks or believes about something','[{"senseId":"opinion_1","meaning":"what a person thinks or believes about something","acceptedParaphrases":["view","personal belief"],"masteryContexts":[{"contextId":"u10_38_opinion_meaning","text":"The teacher asked each student to give their opinion about the book.","meaning":"what someone thinks about something","wrongMeanings":["a fact that can be checked","a summary of the story","a list of characters"]},{"contextId":"u10_38_opinion_paraphrase","text":"Public opinion has turned against the plan to close the library.","meaning":"what most people in a society think","wrongMeanings":["the laws of a country","the money a country spends","the leaders of a country"]}],"situationDistractors":["A student wrote that water boils at one hundred degrees.","The government published a new law about driving.","A maths question asked what seven times eight is.","A student measured the length of a table.","A teacher wrote the date on the board.","A boy looked up the capital of France."],"gapDistractors":[{"contextId":"u10_38_opinion_gap_1","answer":"opinion","wrong":["loneliness","literacy","recreation"]},{"contextId":"u10_38_opinion_gap_2","answer":"opinion","wrong":["loneliness","literacy","recreation"]},{"contextId":"u10_38_opinion_gap_3","answer":"opinion","wrong":["loneliness","literacy","recreation"]}],"spellingErrors":["oppinion","opinon","opinnion","opineon","opion","oppinon"],"masteryPassages":[{"passageId":"u10_38_opinion_passage_1","contextId":"u10_38_opinion_gap_1","text":"Some people think homework is useful, but others disagree. In my ____, a small amount of homework helps students remember what they learn.","answer":"opinion"},{"passageId":"u10_38_opinion_passage_2","contextId":"u10_38_opinion_gap_2","text":"The teacher asked each student what they thought of the novel. Most students gave a positive ____.","answer":"opinion"}],"contextDependentParaphrases":[],"wrongParaphrases":["fact","law","calculation"],"misleadingDistractors":["a fact that everyone agrees is true","a rule written by the government","a question with only one correct answer"],"teacherNote":"Noun: what someone thinks about something (in my opinion, give / express your opinion, a strong opinion, public opinion). Countable. Boundary: an opinion is a personal belief; a fact can be checked. Useful phrases for Paper 2 opinion writing: In my opinion, ...; Some people are of the opinion that ..."}]'::jsonb,'[]'::jsonb,'["in my opinion","give your opinion","public opinion"]'::jsonb,'live'),
('vocab_discussion','discussion','noun','a conversation in which people talk about a subject and share their ideas and opinions','[{"senseId":"discussion_1","meaning":"a conversation in which people talk about a subject and share their ideas and opinions","acceptedParaphrases":["talk","exchange of views"],"masteryContexts":[{"contextId":"u10_39_discussion_meaning","text":"The teacher divided us into groups for a discussion about climate change.","meaning":"a talk in which people share ideas","wrongMeanings":["a speech given by one person","a test taken in silence","a game played in teams"]},{"contextId":"u10_39_discussion_paraphrase","text":"The new uniform policy is still under discussion, so nothing has been decided.","meaning":"the process of being talked about before a decision","wrongMeanings":["the process of being cancelled","the process of being advertised","the process of being forgotten"]}],"situationDistractors":["A famous author gave a speech and left without answering questions.","Students sat a reading test in silence.","Two boys started pushing each other in the corridor.","A teacher read out a notice and left.","A boy worked silently on his own.","Two girls ignored each other all day."],"gapDistractors":[{"contextId":"u10_39_discussion_gap_1","answer":"discussion","wrong":["loneliness","literacy","recreation"]},{"contextId":"u10_39_discussion_gap_2","answer":"discussion","wrong":["loneliness","literacy","recreation"]},{"contextId":"u10_39_discussion_gap_3","answer":"discussion","wrong":["loneliness","literacy","recreation"]}],"spellingErrors":["discusion","disscussion","discution","discussoin","diskussion","discusssion"],"masteryPassages":[{"passageId":"u10_39_discussion_passage_1","contextId":"u10_39_discussion_gap_1","text":"Our class talked for an hour about whether phones should be banned at school. It was a lively ____, and everyone shared their views.","answer":"discussion"},{"passageId":"u10_39_discussion_passage_2","contextId":"u10_39_discussion_gap_2","text":"The council has not decided whether to close the library. The plan is still under ____.","answer":"discussion"}],"contextDependentParaphrases":[],"wrongParaphrases":["speech","silence","fight"],"misleadingDistractors":["a speech given by one person with no questions","a written test in silence","an argument that ends in a fight"],"teacherNote":"Noun: a conversation in which people share ideas about a subject (have a discussion about, a class discussion, under discussion). Countable. Boundary: a discussion is an exchange of views; an argument suggests disagreement and strong feelings. The verb discuss (discuss something, not *discuss about) is taught in the Word Family pathway."}]'::jsonb,'[]'::jsonb,'["a class discussion","have a discussion about","under discussion"]'::jsonb,'live'),
('vocab_succeed','succeed','verb','to achieve something that you have been trying to do','[{"senseId":"succeed_1","meaning":"to achieve something that you have been trying to do","acceptedParaphrases":["do well","achieve your aim"],"masteryContexts":[{"contextId":"u10_40_succeed_meaning","text":"After three attempts, she hopes to succeed in her driving test this time.","meaning":"to manage to do something difficult","wrongMeanings":["to give up trying","to forget to try","to try for the first time"]},{"contextId":"u10_40_succeed_paraphrase","text":"The school helps every student succeed, whatever their background.","meaning":"to do well in study or life","wrongMeanings":["to fail in study or life","to leave school early","to move to another school"]}],"situationDistractors":["A boy stopped running halfway through the race.","A girl tried ice skating for the very first time.","A student sent the wrong file to her teacher.","A girl dropped out of the race halfway.","A boy’s plan to build a raft sank immediately.","A student failed the test for the third time."],"gapDistractors":[{"contextId":"u10_40_succeed_gap_1","answer":"succeed","wrong":["encourage","evaluate","communicate"]},{"contextId":"u10_40_succeed_gap_2","answer":"succeed","wrong":["encourage","evaluate","develop"]},{"contextId":"u10_40_succeed_gap_3","answer":"succeed","wrong":["encourage","evaluate","reflect"]}],"spellingErrors":["succed","suceed","sucseed","succeeed","succede","sucede"],"wordFamilyForms":[{"form":"succeed","partOfSpeech":"verb","example":"With hard work, you will succeed.","pedagogicallyUseful":true},{"form":"success","partOfSpeech":"noun","example":"The concert was a great success.","pedagogicallyUseful":true,"altExample":"Her success in the competition made the newspapers."},{"form":"successful","partOfSpeech":"adjective","example":"He runs a successful business in the city.","pedagogicallyUseful":true,"altExample":"The fundraising event was very successful."}],"masteryPassages":[{"passageId":"u10_40_succeed_passage_1","contextId":"u10_40_succeed_gap_1","text":"Climbing the mountain took three attempts. On the third try, the team finally managed to ____.","answer":"succeed"},{"passageId":"u10_40_succeed_passage_2","contextId":"u10_40_succeed_gap_2","text":"The new mentoring scheme gives every student support. Its aim is to help everyone ____, whatever their background.","answer":"succeed"}],"contextDependentParaphrases":[],"wrongParaphrases":["give up","start out","go wrong"],"misleadingDistractors":["to give up before the end","to try something for the first time","to make a serious mistake"],"teacherNote":"Verb: to achieve what you have been trying to do (succeed in doing something, succeed at school, succeed in life). Pattern: succeed in + -ing (not *succeed to do). Common spelling error: *succed / *suceed. The noun success, the adjective successful and the adverb successfully are taught in the Word Family pathway."}]'::jsonb,'["success","successful"]'::jsonb,'["succeed in","succeed at school","help someone succeed"]'::jsonb,'live')
